const ASSETS={"logo": "data:image/png;base64,", "symbol": "data:image/png;base64,"};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),date=v=>v?new Date(v).toLocaleString('en-NZ'):'Not yet run';let user=null,csrf='',sites=[],caps={},current=null,audit=null,history=[],documents=[],connection={connected:false},requests=[],view='Overview',filter='All findings',query='',device='mobile',pollTimer,loading=false;const nav=['Overview','Websites','Brand & strategy','Audits','Keywords & pages','Performance & audience','Action plan','Reports','Connections','Website access','Help'];const sections={summary:true,technical:true,seo:true,ai:true,performance:true,analytics:true,plan:true};
async function api(path,{method='GET',data}={}){const res=await fetch('/api'+path,{method,headers:{...(data?{'Content-Type':'application/json'}:{}),...(method!=='GET'?{'X-CSRF-Token':csrf}:{})},...(data?{body:JSON.stringify(data)}:{})});const d=await res.json();if(!res.ok){if(res.status===401&&path!=='/auth/login'){user=null;csrf='';clearTimeout(pollTimer);render()}throw Error(d.error||'Request failed.')}return d}
function button(t,act,cls='',attrs=''){return '<button type="button" class="btn '+cls+'" data-act="'+act+'" '+attrs+'>'+t+'</button>'}
function heading(t,d,a=''){return '<div class="head"><div><div class="eyebrow">SYNERGY HUB / AUDIT STUDIO</div><h1>'+t+'</h1><p>'+d+'</p></div><div class="actions">'+a+'</div></div>'}
function pill(t,cls=''){return '<span class="pill '+cls+'">'+esc(t)+'</span>'}
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,6000)}
function modal(t,body,footer='',wide=false){$('#modal-root').innerHTML='<div class="modal-backdrop"><section class="modal '+(wide?'wide':'')+'" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="line-head"><h2 id="dialog-title">'+esc(t)+'</h2>'+button('×','close','close')+'</div>'+body+(footer?'<div class="actions spacer">'+footer+'</div>':'')+'</section></div>';$('#modal-root .close').focus()}
function closeModal(){$('#modal-root').innerHTML=''}
function field(n,label,v='',type='text'){return '<label class="field">'+label+(type==='textarea'?'<textarea name="'+n+'">'+esc(v)+'</textarea>':'<input name="'+n+'" type="'+type+'" value="'+esc(v)+'">')+'</label>'}
function formData(selector){const out={};for(const el of $(selector).querySelectorAll('[name]'))out[el.name]=el.type==='checkbox'?el.checked:el.value;return out}
function table(head,rows){return '<div class="table-wrap"><table class="data-table"><thead><tr>'+head.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table></div>'}
const result=()=>audit?.result||null,findings=()=>result()?.findings||[],profile=()=>current?.profile||{},busy=()=>history.find(a=>['queued','running'].includes(a.status));
function ring(n,c='#9170ca'){if(n===null||n===undefined||!Number.isFinite(n))return '<div class="score-na" aria-label="Not measured">—</div>';return '<div class="score-ring"><svg viewBox="0 0 110 110" role="img" aria-label="'+n+' out of 100"><circle cx="55" cy="55" r="46" fill="none" stroke="currentColor" opacity=".09" stroke-width="7"/><circle cx="55" cy="55" r="46" fill="none" stroke="'+c+'" stroke-width="7" stroke-linecap="round" stroke-dasharray="'+(n/100*289)+' 289"/></svg><div class="ring-text"><b>'+n+'</b><span>/ 100</span></div></div>'}
function metrics(){const r=result();return '<div class="grid five">'+[['Website health',r?.scores.technical,'HTML check pass rate'],['SEO checks',r?.scores.seo,'On-page check pass rate'],['AIO assessment',null,r?.ai?.available?'Editorial findings below':'Not assessed'],['Brand alignment',null,r?.ai?.available?'Editorial findings below':'Not assessed'],['Mobile performance',r?.scores.speed,r?.performance?.devices?.mobile?.available?'Lighthouse lab result':'Not measured']].map(([t,v,s])=>'<section class="card score-card"><h3>'+t+'</h3>'+ring(v)+'<div class="bottom"><span>'+s+'</span></div></section>').join('')+'</div>'}
function login(){return '<div class="login"><div class="login-art"><img class="hub-logo" src="'+ASSETS.logo+'" alt="Synergy Hub"><div class="eyebrow" style="margin-top:30px;color:#bc9cde">AUDIT STUDIO</div><h1>Your website.<br>Your brand.<br>A clearer direction.</h1><p>Bring your website, search data and strategy together. See what matters, understand why, and know what to do next.</p><div class="actions" style="margin-top:30px">'+pill('Website health','green')+pill('SEO & AIO')+pill('Brand alignment')+'</div></div><div class="login-form"><section class="card"><div class="eyebrow">WELCOME TO SYNERGY HUB</div><h2>Let’s take a closer look.</h2><p class="muted" style="margin:15px 0 25px">Sign in to your private audit workspace.</p><form id="login-form">'+field('email','Email','','email')+field('password','Password','','password')+'<button class="btn primary" type="submit">Sign in →</button></form><p class="inline-note">Need access or a password reset? Contact your Synergy Hub administrator. Your login is separate from Google authorisation.</p></section></div></div>'}
function render(){if(!user){$('#app').innerHTML=login();return}const running=busy();$('#app').innerHTML='<div class="shell"><aside class="side"><img class="hub-logo" src="'+ASSETS.logo+'" alt="Synergy Hub"><div class="workspace"><div class="eyebrow">AUDIT STUDIO</div><b>'+esc(profile().name||user.name)+'</b><small>Your clarity. Your next move.</small></div><nav class="nav" aria-label="Main navigation">'+nav.map(n=>'<button data-view="'+n+'" '+(view===n?'aria-current="page"':'')+'>'+n+'</button>').join('')+'</nav><div class="side-foot">One view. A clearer plan.<br>Built for ambitious businesses.<button data-act="logout">Sign out</button></div></aside><div class="main"><header class="top"><span class="crumb">Audit studio / <b>'+esc(view)+'</b></span><div class="top-actions"><select id="active-site" aria-label="Selected website" style="border:1px solid #e8e0ef;padding:9px;border-radius:8px;max-width:250px">'+(sites.length?sites.map(s=>'<option value="'+s.id+'" '+(current?.id===s.id?'selected':'')+'>'+esc(s.name)+'</option>').join(''):'<option>Add your website</option>')+'</select>'+button(running?'Audit running…':'Run audit','run','primary',(!current||running?'disabled':''))+'<span class="avatar">'+esc(user.name.slice(0,2).toUpperCase())+'</span></div></header><main class="content">'+(running?'<div class="banner" role="status"><b>'+esc(running.progress?.stage||'Audit queued')+'</b> · '+(running.progress?.pages||0)+' pages checked. You can leave this screen; progress is saved on the server.</div>':'')+(history[0]?.status==='failed'?'<div class="error-note">Latest audit could not complete: '+esc(history[0].error)+'</div>':'')+(!current&&view!=='Websites'?heading('Your next step starts here.','Add your website to run a real public-page audit.',button('+ Add website','add-site','primary')):screen())+'<div class="footer"><span>Synergy Hub · Clarity for your next move.</span><span>Saved to your business workspace</span></div></main></div></div>'+button('<img src="'+ASSETS.symbol+'" alt="">Ask Synergy','assistant','assistant')}
function screen(){return {'Overview':overview,'Websites':websites,'Brand & strategy':brand,'Audits':audits,'Keywords & pages':keywords,'Performance & audience':performance,'Action plan':plan,'Reports':reports,'Connections':connections,'Website access':access,'Help':help}[view]()}
function noAudit(){return '<section class="card"><h2>Your first real audit starts here.</h2><p class="muted spacer">Run an audit to collect HTML evidence from public pages. Speed results require the configured performance service. No sample scores are shown.</p>'+button('Run website audit','run','primary spacer')+'</section>'}
function overview(){const r=result();return heading('A clearer picture. A smarter next step.','Your website performance, search readiness and brand direction—together in one place.',button('View report ↗','reports'))+(!r?noAudit():'<section class="card hero"><div><div class="eyebrow">'+esc(r.url)+'</div><h2>Your evidence.<br>Your next move.</h2><p>'+r.pages.length+' public pages examined. '+findings().length+' findings to review. '+(r.truncated?'Crawl limit reached; additional pages may exist.':'This is a bounded crawl, not a complete index of the internet.')+'</p><div class="actions">'+button('Explore findings →','audits','light')+button('Build your action plan','plan','light')+'</div></div><div class="hero-health">'+ring(r.scores.technical,'#c5e9d6')+'<div>'+pill('Observed HTML checks','green')+'<p style="margin-top:10px">'+date(audit.finished_at)+'<br>No ranking or AI inclusion guarantee.</p></div></div></section><div class="spacer">'+metrics()+'</div><div class="grid two spacer"><section class="card"><h2>Your next moves</h2>'+findings().slice(0,4).map(f=>'<div class="list-row"><span class="priority-dot"></span><div class="grow"><h3>'+esc(f.title)+'</h3><p>'+esc(f.area)+' · '+esc(f.url)+'</p></div><button class="btn small" data-finding="'+f.id+'">Review</button></div>').join('')+(findings().length?'':'<p class="inline-note">No issues found by the checks run. This does not imply a complete or error-free website.</p>')+'</section><section class="card"><h2>Your strategy, connected</h2><div class="quote">'+esc(profile().goals||'Add your goals to guide content and brand assessments.')+'</div>'+button('Review brand & strategy','brand')+'<p class="inline-note">'+documents.length+' stored documents · '+(r.ai?.available?'AI editorial analysis available.':esc(r.ai?.reason||'AI analysis unavailable.'))+'</p></section></div><p class="source-note">'+esc(r.methodology)+'</p>')}
function websites(){return heading('Your websites','Each website has its own brand, audit history, connections and action plan.',button('+ Add website','add-site','primary'))+'<div class="grid three">'+sites.map(s=>'<section class="card"><div class="line-head">'+pill(s.id===current?.id?'Selected website':'Website',s.id===current?.id?'green':'')+'<button class="btn small" data-remove-site="'+s.id+'">Remove</button></div><h2>'+esc(s.name)+'</h2><p class="page-url muted spacer">'+esc(s.url)+'</p><div class="actions spacer"><button class="btn primary" data-select-site="'+s.id+'">Open workspace</button><button class="btn" data-edit-site="'+s.id+'">Settings</button></div></section>').join('')+'</div>'}
function brand(){const p=profile();return heading('Your brand. Your direction.','Confirm the context used in brand and editorial analysis.',button('Save brand & strategy','save-brand','primary'))+'<form id="brand-form"><div class="grid two"><section class="card"><h2 style="margin-bottom:20px">Business & brand voice</h2>'+field('name','Business name',p.name)+field('voice','How should your business sound?',p.voice,'textarea')+field('audience','Who are you trying to reach?',p.audience,'textarea')+field('services','Priority services or products',p.services,'textarea')+field('goals','Business goals & campaign priorities',p.goals,'textarea')+field('keywords','Focus topics & search phrases',p.keywords)+field('messages','Key messages & positioning',p.messages,'textarea')+field('locations','Target locations',p.locations)+'</section><div><section class="card"><h2>Visual identity</h2>'+(p.logo?'<img class="logo-preview spacer" src="'+p.logo+'" alt="Business logo">':'')+'<label class="field spacer">Upload logo<input id="logo-upload" type="file" accept="image/png,image/jpeg,image/webp"><small>Max 2 MB. Saved in your workspace and used in reports.</small></label>'+field('colour','Primary brand colour',p.colour||'#8657db','color')+field('font','Brand fonts',p.font)+'</section><section class="card spacer"><h2>Guidelines & strategy documents</h2><p class="inline-note">Upload reviewed TXT or Markdown text. PDF/DOCX extraction is not enabled; paste extracted text into a text document first.</p><input type="file" id="document-upload" accept=".txt,.md,text/plain,text/markdown" class="spacer">'+documents.map(d=>'<div class="file-row"><b>'+esc(d.name)+'</b><button class="btn small" data-delete-document="'+d.id+'">Remove</button></div>').join('')+'</section><section class="card spacer"><h2>AI analysis permission</h2><label class="field spacer"><span><input type="checkbox" name="aiConsent" '+(p.aiConsent?'checked':'')+'> Send this website’s brand context, stored document text and public-page extracts to the configured AI provider when I run an audit.</span></label><p class="inline-note">'+(caps.ai?'Provider configured. AI output is labelled as editorial advice for review.':'AI provider is not configured. Technical audits work without it.')+' Do not upload passwords, API keys or sensitive customer data.</p></section></div></div></form>'}
function auditRows(list){return table(['Priority','Finding','Area / evidence','Status',''],list.map(f=>'<tr><td>'+pill(f.priority,f.priority==='High'?'red':f.priority==='Medium'?'orange':'')+'</td><td><b>'+esc(f.title)+'</b><small>'+esc(f.url)+'</small></td><td>'+esc(f.area)+'<small>'+esc(f.kind)+'</small></td><td>'+esc(current.tasks[f.id]||'To do')+'</td><td><button class="btn small" data-finding="'+f.id+'">Details ↗</button></td></tr>'))}
function audits(){const r=result();return heading('From findings to direction.','Evidence gathered from the public HTML returned by the selected website.',button('Report preview','reports'))+'<section class="card audit-history"><h3>Audit history</h3><div class="actions spacer"><select id="audit-selection" style="max-width:100%;padding:10px;border:1px solid #ddd;border-radius:7px"><option value="">Select a completed audit</option>'+history.map(a=>'<option value="'+a.id+'" '+(audit?.id===a.id?'selected':'')+' '+(a.status!=='complete'?'disabled':'')+'>'+date(a.created_at)+' · '+esc(a.status)+'</option>').join('')+'</select>'+pill(history.length+' saved runs')+'</div></section>'+(!r?noAudit():metrics()+'<section class="card spacer"><div class="line-head"><h2>Audit findings</h2><input class="search" id="finding-search" placeholder="Search findings…" value="'+esc(query)+'" style="max-width:250px"></div><div class="tabs">'+['All findings','Website health','SEO','AIO','Brand alignment'].map(n=>'<button data-filter="'+n+'" class="'+(filter===n?'active':'')+'">'+n+'</button>').join('')+'</div>'+auditRows(findings().filter(f=>(filter==='All findings'||f.area===filter)&&(f.title+' '+f.url).toLowerCase().includes(query.toLowerCase())))+'</section><section class="card spacer"><h2>Crawl coverage & limitations</h2><p class="inline-note">'+r.pages.length+' pages · max '+r.limits.maxPages+' pages per run · '+r.skipped.length+' skipped URLs. JavaScript is not rendered by this HTML crawler. External link destinations, full accessibility and cross-browser interactions are not tested.</p>'+r.skipped.slice(0,15).map(p=>'<p class="inline-note">'+esc(p.url)+' — '+esc(p.reason)+'</p>').join('')+'</section>')}
function keywords(){const manual=current.keywords||[],generated=(result()?.ai?.keywords||[]).map((k,i)=>({...k,id:'suggestion-'+audit.id+'-'+i,status:'To review'})),merged=[...manual,...generated.filter(k=>!manual.some(m=>m.id===k.id))];return heading('The right words. The right pages.','AI suggestions use page evidence and confirmed brand context. Search Console queries are separate measured data.',button('+ Add your own idea','add-keyword','primary'))+'<section class="card"><div class="tag-list">'+String(profile().keywords||'').split(',').filter(Boolean).map(t=>pill(t.trim())).join('')+'</div><p class="inline-note">Search demand, search volume and competition are not supplied by this service. Recommendations are not measured rankings.</p>'+table(['Focus phrase','Page','Status',''],merged.map(k=>'<tr><td><b>'+esc(k.phrase)+'</b><small>'+esc(k.reason)+'</small></td><td>'+esc(k.page)+'</td><td>'+pill(k.status)+'</td><td><button class="btn small" data-keyword="'+esc(k.id)+'">Review</button></td></tr>'))+(merged.length?'':'<div class="empty">Add a focus phrase or enable brand analysis and run an audit for evidence-led suggestions.</div>')+'</section>'}
function performance(){const r=result(),p=r?.performance?.devices?.[device],g=connection.data;return heading('Performance. Audience. A clearer view.','Lab measurements and analytics are separate data sources.',button('Manage connections','connections'))+'<section class="card"><div class="line-head"><h2>Website speed</h2><div class="tabs" style="margin:0;padding:0;border:0">'+['mobile','desktop'].map(d=>'<button data-device="'+d+'" class="'+(device===d?'active':'')+'">'+d+'</button>').join('')+'</div></div>'+(p?.available?'<div class="grid four"><section class="score-card">'+ring(p.score)+'<p class="inline-note">Lighthouse performance score</p></section>'+[['LCP',p.lcp===null?'Unavailable':(p.lcp/1000).toFixed(2)+' s','Lab largest contentful paint'],['CLS',p.cls===null?'Unavailable':p.cls.toFixed(3),'Lab layout shift'],['TBT',p.tbt===null?'Unavailable':Math.round(p.tbt)+' ms','Lab blocking time—not INP']].map(([n,v,note])=>'<section class="score-card"><h3>'+n+'</h3><div class="stat">'+v+'</div><p class="inline-note">'+note+'</p></section>').join('')+'</div><p class="source-note">Measured '+date(p.fetchedAt)+' · Lighthouse '+esc(p.lighthouseVersion)+' · '+esc(p.finalURL)+'</p><div class="quote">Field experience: '+esc(p.field?.category||'No field data supplied. Lab tests do not establish a Core Web Vitals field pass.')+'</div>'+p.opportunities.map(o=>'<div class="list-row"><div class="grow"><h3>'+esc(o.title)+'</h3><p>Estimated lab saving: '+Math.round(o.savingsMs)+' ms. Validate before making changes.</p></div></div>').join(''):'<div class="empty">'+esc(p?.reason||r?.performance?.reason||'Run an audit with performance measurement enabled. No sample scores are substituted.')+'</div>')+'</section>'+analyticsHTML(g)}
function analyticsHTML(g){if(!g)return '<section class="card spacer"><h2>Your audience and search performance</h2><p class="inline-note">Connect Google, select properties and refresh data to see real top pages, countries, cities and search queries.</p>'+button('Connect Google','connections','primary spacer')+'</section>';const a=g.analytics,s=g.search;return '<section class="card spacer"><h2>Connected performance data</h2><p class="source-note">Last refreshed '+date(g.fetchedAt)+'. '+(g.syncing?'Refresh in progress. ':'')+'GA4 visitor metrics and Search Console search clicks are different measures.</p>'+(g.errors||[]).map(e=>'<div class="error-note">'+esc(e)+'</div>').join('')+'</section>'+(a?.totals?'<div class="grid four spacer">'+Object.entries(a.totals).map(([k,v])=>'<section class="card"><h3>'+esc(k)+'</h3><div class="stat">'+Number(v).toLocaleString()+'</div><p class="inline-note">GA4 · '+a.range.startDate+' to '+a.range.endDate+'</p></section>').join('')+'</div>':'')+(a?'<div class="grid two spacer">'+[['Top 10 pages','pages','Views'],['Audience countries','countries','Active users'],['Audience cities','cities','Active users'],['Acquisition channels','channels','Sessions']].map(([t,key,label])=>'<section class="card"><h2>'+t+'</h2>'+table(['Name',label],(a[key]||[]).map(r=>'<tr><td>'+esc(r.name)+'</td><td>'+r.value.toLocaleString()+'</td></tr>'))+'<p class="source-note">'+esc(a.source)+'. Approximate locations; withheld and unknown values may appear. Country and city rows are not additive.</p></section>').join('')+'</div>':'')+(s?'<section class="card spacer"><h2>Search queries & page visibility</h2><p class="source-note">'+s.range.startDate+' to '+s.range.endDate+' · '+esc(s.source)+'</p>'+table(['Query','Clicks','Impressions','Avg position'],(s.query||[]).map(q=>'<tr><td>'+esc(q.keys[0])+'</td><td>'+q.clicks+'</td><td>'+q.impressions+'</td><td>'+q.position.toFixed(1)+'</td></tr>'))+'<h3 class="spacer">Top search pages</h3>'+table(['Page','Clicks','Impressions'],(s.page||[]).map(p=>'<tr><td>'+esc(p.keys[0])+'</td><td>'+p.clicks+'</td><td>'+p.impressions+'</td></tr>'))+'</section>':'')}
function plan(){return heading('Make the next move clear.','Task progress is stored on the server. It does not change your website or remeasure scores.',button('Download action plan CSV','csv'))+'<div class="grid three">'+['To do','In progress','Done'].map(status=>'<section class="card"><h2>'+status+'</h2>'+findings().filter(f=>(current.tasks[f.id]||'To do')===status).map(f=>'<article style="border:1px solid #ece5f0;padding:17px;border-radius:10px;margin-top:15px">'+pill(f.priority)+'<h3 style="margin:12px 0;font-size:14px">'+esc(f.title)+'</h3><p class="inline-note">'+esc(f.area)+'</p><div class="actions spacer"><select data-task="'+f.id+'" style="max-width:100%;padding:8px">'+['To do','In progress','Done'].map(s=>'<option '+(s===status?'selected':'')+'>'+s+'</option>').join('')+'</select><button class="btn small" data-finding="'+f.id+'">Review</button></div></article>').join('')+'</section>').join('')+'</div>'}
function reportHTML(){const r=result();if(!r)return noAudit();let html='<article class="report"><div class="report-top"><div>'+(profile().logo?'<img class="report-logo" src="'+profile().logo+'" alt="Business logo">':'<h2>'+esc(profile().name||current.name)+'</h2>')+'<p class="muted" style="font-size:10px;margin-top:8px">WEBSITE · SEO · AIO · BRAND ALIGNMENT</p></div>'+pill('SYNERGY HUB REPORT')+'</div><div class="eyebrow">AUDIT / '+date(audit.finished_at)+'</div><h1>Your website.<br>A clearer direction.</h1><p class="spacer page-url">'+esc(r.url)+'</p><div class="banner spacer">Evidence from '+r.pages.length+' public HTML pages. '+esc(r.methodology)+'</div>';if(sections.summary)html+='<section class="report-section"><h2>Executive summary</h2>'+metrics()+'<p class="spacer">'+findings().length+' observed findings and editorial recommendations. '+esc(r.ai?.available?r.ai.summary:r.ai?.reason||'AI analysis not available.')+'</p></section>';for(const [key,area]of [['technical','Website health'],['seo','SEO']])if(sections[key])html+='<section class="report-section"><h2>'+area+'</h2>'+findings().filter(f=>f.area===area).map(f=>'<div style="margin:18px 0"><h3>'+esc(f.title)+'</h3><p class="page-url">'+esc(f.url)+'</p><p><b>Evidence:</b> '+esc(f.evidence)+'</p><p><b>Next step:</b> '+esc(f.fix)+'</p></div>').join('')+'</section>';if(sections.ai)html+='<section class="report-section"><h2>AIO & brand alignment</h2><p>These are editorial assessments, not measurements of AI visibility or ranking.</p>'+findings().filter(f=>['AIO','Brand alignment'].includes(f.area)).map(f=>'<h3>'+esc(f.title)+'</h3><p>'+esc(f.url)+'</p><p>'+esc(f.evidence)+'</p><p>'+esc(f.fix)+'</p>').join('')+(r.ai?.available?'':'<p>'+esc(r.ai?.reason||'Not assessed.')+'</p>')+'</section>';if(sections.performance)html+='<section class="report-section"><h2>Mobile & desktop performance</h2>'+['mobile','desktop'].map(d=>{const p=r.performance?.devices?.[d];return '<h3>'+d+'</h3><p>'+(p?.available?'Lighthouse score '+p.score+'/100 · lab LCP '+(p.lcp===null?'unavailable':(p.lcp/1000).toFixed(2)+' s')+' · CLS '+(p.cls??'unavailable')+' · lab TBT '+(p.tbt===null?'unavailable':Math.round(p.tbt)+' ms')+'. '+esc(p.field?'Field category: '+p.field.category:'No field measurement supplied.') :esc(p?.reason||r.performance?.reason||'Not measured.'))+'</p>'}).join('')+'<p class="source-note">Lab TBT is not field INP. Performance varies by test conditions. Measurements apply to the tested page, not every crawled page.</p></section>';if(sections.analytics)html+='<section class="report-section"><h2>Audience & search data</h2>'+analyticsHTML(connection.data)+'</section>';if(sections.plan)html+='<section class="report-section"><h2>Prioritised action plan</h2>'+table(['Action','Priority','Status'],findings().map(f=>'<tr><td>'+esc(f.title)+'</td><td>'+f.priority+'</td><td>'+esc(current.tasks[f.id]||'To do')+'</td></tr>'))+'</section>';return html+'<section class="report-section"><h2>Sources & limits</h2><p>Crawl captured '+date(r.createdAt)+'. Audit ID '+esc(audit.id)+'. '+(r.truncated?'Crawl limit reached. ':'')+r.skipped.length+' skipped URLs. Returned HTML only; JavaScript interactions, external-link destinations, full accessibility and cross-browser behaviour are not tested. AI output is for human review. Google data is separately timestamped and may cover a different reporting period. No guarantee of rankings or appearance in AI responses.</p></section><footer class="report-footer"><span>Prepared with Synergy Hub</span><span>'+esc(current.name)+'</span></footer></article>'}
function reports(){return heading('A report worth sharing.','Choose your sections. Download a PDF summary or print the full designed report.',button('Download PDF ↓','pdf','primary')+button('Print report','print')+button('Download audit JSON','audit-json'))+'<section class="card report-controls"><h3>Included sections</h3><div class="actions spacer">'+Object.entries({summary:'Summary',technical:'Website health',seo:'SEO',ai:'AIO & brand',performance:'Speed',analytics:'Audience & search',plan:'Action plan'}).map(([k,v])=>'<label style="font-size:11px;display:flex;align-items:center;gap:7px"><input type="checkbox" data-section="'+k+'" '+(sections[k]?'checked':'')+'>'+v+'</label>').join('')+'</div><p class="inline-note">Print includes only the report. Choose “Save as PDF” in your browser to retain the visual layout and full Unicode text.</p></section>'+reportHTML()}
function connections(){const settings=connection.settings||{};return heading('Your data. A fuller picture.','Public HTML audits work without Google. Authorise read-only access to add your own analytics.')+'<div class="grid two"><section class="card"><h2>Google Search Console & Analytics</h2><div class="spacer">'+pill(connection.connected?'Authorisation stored':'Not connected',connection.connected?'green':'orange')+'</div><p class="inline-note">'+(caps.google?'Connect your account, choose matching properties, then refresh data.':'Your Hub administrator must configure Google authorisation before connecting.')+'</p><div class="actions spacer">'+(connection.connected?button('Choose properties','google-properties','primary')+button(connection.data?.syncing?'Refreshing Google data…':'Refresh Google data','google-sync','',connection.data?.syncing?'disabled':'')+button('Disconnect','google-disconnect'):button('Connect Google','google-start','primary',caps.google?'':'disabled'))+'</div><p class="inline-note">Search Console: '+esc(settings.searchProperty||'No property selected')+'<br>GA4: '+esc(settings.analyticsProperty||'No property selected')+'</p>'+(connection.data?.errors||[]).map(e=>'<div class="error-note">'+esc(e)+'</div>').join('')+'</section><section class="card"><h2>Performance & AI providers</h2><div class="list-row"><div class="grow"><h3>PageSpeed Insights</h3><p>Mobile and desktop Lighthouse measurements.</p></div>'+pill(caps.pagespeed?'Configured':'Not configured',caps.pagespeed?'green':'orange')+'</div><div class="list-row"><div class="grow"><h3>AI editorial analysis</h3><p>Requires provider configuration and your brand-analysis permission.</p></div>'+pill(caps.ai?'Configured':'Not configured',caps.ai?'green':'orange')+'</div><p class="inline-note">Keys are stored by the server administrator, never in the browser. Configured does not mean a live request has succeeded.</p></section></div><section class="card spacer"><h2>Other engines and browsers</h2><p class="muted spacer">This release does not connect Bing, run AI-answer visibility searches, or launch Chrome, Firefox or Safari. These features are not represented as active. The public crawler analyses returned HTML; Lighthouse performance is a separate Google service.</p></section>'}
function access(){const a=current.access||{};return heading('Safe access. Clear approvals.','Store access instructions and request review of recommendations.',button('Request implementation','request-work','primary'))+'<div class="grid two"><section class="card"><h2>Website access preferences</h2><form id="access-form" class="spacer">'+field('loginUrl','Website login URL',a.loginUrl,'url')+field('method','Preferred access method',a.method||'Invite a dedicated website user')+field('notes','Access instructions · no passwords, tokens or keys',a.notes,'textarea')+'</form>'+button('Save access preferences','save-access','primary')+'</section><section class="card"><h2>No credential vault in this release.</h2><p class="muted spacer">Arrange an invitation to a dedicated website user account. Do not paste credentials into documents, instructions or AI context.</p><div class="quote">Requests are saved for review. They do not authorise website changes, create charges or send an email.</div></section></div><section class="card spacer"><h2>Implementation requests</h2>'+requests.map(r=>'<div class="list-row"><div class="grow"><h3>'+esc(r.id)+'</h3><p>'+esc(r.note)+'</p><p>'+date(r.created_at)+' · '+r.findings.length+' findings</p></div>'+pill('Requested · saved for review')+'</div>').join('')+(requests.length?'':'<p class="inline-note">No requests for this website.</p>')+'</section>'}
function help(){return heading('Get clear. Get moving.','Synergy Hub guides for your live audit workspace.')+'<div class="grid three">'+[['Start with a website','Add a full public URL. The crawler respects robots.txt, stays within the selected website and limits page count and runtime.','Websites'],['Give the audit context','Save your audience, voice and goals. Upload reviewed text documents. AI analysis is opt-in and requires a configured provider.','Brand & strategy'],['Read the evidence','Technical results come from returned HTML. Speed results are Google lab measurements. Editorial assessments are labelled separately.','Audits'],['Track changes','Task status and approved drafts stay in the database. A new audit is needed to verify website changes.','Action plan'],['Share a report','Download a PDF summary, JSON evidence or CSV action plan. Print only the report for the full visual layout.','Reports'],['Connect Google','The business authorises access, selects its properties and refreshes data. Only observed provider data is displayed.','Connections']].map(([t,d,v])=>'<section class="card help-card">'+pill('SYNERGY HUB GUIDE')+'<h3 class="spacer">'+t+'</h3><p>'+d+'</p><button class="btn small" data-view="'+v+'">Open '+v+'</button></section>').join('')+'</div><section class="card spacer"><h2>First release boundaries</h2><p class="inline-note">Runs are started manually. Billing, scheduled audits, outgoing notifications, PDF/DOCX extraction, a credential vault and automated website editing are not enabled. Ask your administrator about backups, account resets and provider setup. No sample data or pretend connection is substituted.</p></section>'}
function finding(id){const f=findings().find(f=>f.id===id);if(!f)return;modal(f.title,'<div class="actions">'+pill(f.priority,f.priority==='High'?'red':'orange')+pill(f.kind)+'</div><p class="muted page-url spacer">'+esc(f.url)+'</p><h3 class="spacer">What we found</h3><div class="quote">'+esc(f.evidence)+'</div><h3>Why it matters</h3><p class="muted spacer">'+esc(f.impact)+'</p><h3 class="spacer">Your next step</h3><p class="spacer">'+esc(f.fix)+'</p><label class="field spacer">Draft / implementation notes · review before use<textarea id="draft-text" style="min-height:130px">'+esc(current.drafts[id]||f.draft||'')+'</textarea></label><p class="inline-note">Saving notes does not edit your website or verify the recommendation.</p>',button('Save notes','save-draft','primary','data-id="'+id+'"'),true)}
function siteDialog(id){const s=sites.find(s=>s.id===id);modal(s?'Website settings':'Add a website','<form id="site-form" data-id="'+(id||'')+'">'+field('name','Website name',s?.name||'The Synergy Creative')+field('url','Website URL',s?.url||'https://thesynergycreative.nz/','url')+'<p class="inline-note">Use a public website you manage or have permission to audit. Private networks, custom ports and protected areas are not crawled.</p></form>',button('Save website','save-site','primary'))}
async function loadSites(select){const d=await api('/sites');sites=d.sites;caps=d.capabilities;const chosen=sites.find(s=>s.id===(select||current?.id))||sites[0];if(chosen)await loadSite(chosen.id);else{current=null;audit=null;history=[];render()}}
async function loadSite(id,{keepAudit=false}={}){clearTimeout(pollTimer);const previousRunning=busy()?.id;const d=await api('/sites/'+id);if(current?.id!==id)keepAudit=false;current=d.site;history=d.audits;documents=d.documents;connection=d.connection;requests=d.requests;if(!keepAudit||(previousRunning&&!history.some(a=>a.id===previousRunning&&['queued','running'].includes(a.status))))audit=d.audit;render();if(busy()||connection.data?.syncing)pollTimer=setTimeout(()=>loadSite(id,{keepAudit:!!audit}).catch(e=>toast(e.message)),3000)}
async function changeSite(data){await api('/sites/'+current.id,{method:'PATCH',data});await loadSite(current.id,{keepAudit:true})}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function pdfSummary(){const r=result();if(!r)throw Error('Run an audit first.');const blocks=[['Synergy Hub | Website Audit',22],[profile().name||current.name,14],[r.url,10],['Audit completed '+date(audit.finished_at),10],['Sources and limits',16],[r.methodology,10],[r.pages.length+' public HTML pages; '+findings().length+' findings. JavaScript interactions and cross-browser tests were not run.',10]];if(sections.summary)for(const [k,v]of Object.entries(r.scores))blocks.push([k+': '+(v===null?'not scored':v+'/100'),11]);if(sections.technical||sections.seo||sections.ai)for(const f of findings().filter(f=>f.area==='Website health'?sections.technical:f.area==='SEO'?sections.seo:sections.ai)){blocks.push([f.priority+' | '+f.title,13],[f.url,9],['Evidence: '+f.evidence,10],['Next step: '+f.fix,10],['Action status: '+(current.tasks[f.id]||'To do'),9])}if(sections.performance)for(const d of ['mobile','desktop']){const p=r.performance?.devices?.[d];blocks.push([d+' performance',16],[p?.available?'Lighthouse '+p.score+'/100. LCP '+Math.round(p.lcp||0)+' ms. CLS '+(p.cls??'unavailable')+'. Lab TBT '+Math.round(p.tbt||0)+' ms (not INP).':p?.reason||r.performance?.reason||'Not measured.',10])}if(sections.analytics&&connection.data){const g=connection.data;blocks.push(['Google data',16],['Refreshed '+date(g.fetchedAt),10]);for(const [k,v]of Object.entries(g.analytics?.totals||{}))blocks.push([k+': '+v,10]);for(const p of g.analytics?.pages||[])blocks.push([p.name+' | '+p.value+' views',10]);for(const c of g.analytics?.countries||[])blocks.push([c.name+' | '+c.value+' active users (approximate location)',10]);for(const q of g.search?.query||[])blocks.push([q.keys[0]+' | '+q.clicks+' search clicks | '+q.impressions+' impressions',10])}blocks.push(['Prepared with Synergy Hub. Editorial output needs human review. No rankings or AI visibility guarantee.',10]);const ascii=s=>String(s).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^\x20-\x7e]/g,' ').replace(/[()\\]/g,'\\$&');let y=790,stream='',pages=[];const end=()=>{stream+='BT /F1 8 Tf 45 30 Td (SYNERGY HUB | '+(pages.length+1)+') Tj ET\n';pages.push(stream);stream='';y=790};for(const [txt,size]of blocks){const words=ascii(txt).split(/\s+/),max=size>15?48:90;let line='';const put=()=>{if(y<65)end();stream+='BT /F1 '+size+' Tf 45 '+y+' Td ('+line+') Tj ET\n';y-=size*1.45;line=''};for(const w of words){if((line+' '+w).length>max&&line)put();line+=(line?' ':'')+w}if(line)put();y-=8}if(stream)end();const objects=['<< /Type /Catalog /Pages 2 0 R >>','','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'];pages.forEach((body,i)=>{const cid=5+i*2;objects.push('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> >> /Contents '+cid+' 0 R >>','<< /Length '+body.length+' >>\nstream\n'+body+'endstream')});objects[1]='<< /Type /Pages /Count '+pages.length+' /Kids ['+pages.map((_,i)=>(4+i*2)+' 0 R').join(' ')+'] >>';let pdf='%PDF-1.4\n',offsets=[0];objects.forEach((o,i)=>{offsets.push(pdf.length);pdf+=(i+1)+' 0 obj\n'+o+'\nendobj\n'});const xref=pdf.length;pdf+='xref\n0 '+(objects.length+1)+'\n0000000000 65535 f \n'+offsets.slice(1).map(x=>String(x).padStart(10,'0')+' 00000 n \n').join('')+'trailer\n<< /Size '+(objects.length+1)+' /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF';download('synergy-hub-audit-summary.pdf',pdf,'application/pdf')}
function keywordDialog(id){const generated=(result()?.ai?.keywords||[]).map((k,i)=>({...k,id:'suggestion-'+audit.id+'-'+i,status:'To review'})),k=[...(current.keywords||[]),...generated].find(k=>k.id===id)||{id:'keyword-'+Date.now(),phrase:'',page:'',title:'',reason:'Business-provided idea; validate against page purpose and search demand.',outline:'',status:'To review'};modal('Review keyword & page direction','<form id="keyword-form" data-id="'+esc(k.id)+'">'+field('phrase','Focus phrase',k.phrase)+field('page','Existing or proposed page path',k.page)+field('title','Suggested SEO title',k.title)+field('outline','Page outline / notes',k.outline,'textarea')+field('reason','Reason and evidence',k.reason,'textarea')+'<label class="field">Status<select name="status">'+['To review','Approved','Dismissed'].map(s=>'<option '+(s===k.status?'selected':'')+'>'+s+'</option>').join('')+'</select></label></form><p class="inline-note">This saves a recommendation. It does not publish a page or prove search demand.</p>',button('Save recommendation','save-keyword','primary'))}
document.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id!=='login-form')return;const b=e.target.querySelector('button');b.disabled=true;try{await api('/auth/login',{method:'POST',data:formData('#login-form')});const s=await api('/session');user=s.user;csrf=s.csrf;await loadSites()}catch(err){toast(err.message)}finally{b.disabled=false}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset,a=d.act;try{if(d.view){view=d.view;render();return}if(d.filter){filter=d.filter;render();return}if(d.device){device=d.device;render();return}if(d.finding)return finding(d.finding);if(d.selectSite){view='Overview';return await loadSite(d.selectSite)}if(d.editSite)return siteDialog(d.editSite);if(d.removeSite){const s=sites.find(s=>s.id===d.removeSite);return modal('Remove website?','<p>Removing '+esc(s.name)+' deletes its stored audits, documents and connections from this workspace.</p>',button('Remove website','confirm-remove','dark','data-id="'+s.id+'"'))}if(d.deleteDocument){await api('/sites/'+current.id+'/documents/'+d.deleteDocument,{method:'DELETE'});await loadSite(current.id,{keepAudit:true});return}if(d.keyword)return keywordDialog(d.keyword);if(!a)return;if(a==='close')return closeModal();if(['reports','audits','plan','brand','connections'].includes(a)){view={reports:'Reports',audits:'Audits',plan:'Action plan',brand:'Brand & strategy',connections:'Connections'}[a];render();return}if(a==='logout'){await api('/auth/logout',{method:'POST'});user=null;current=null;clearTimeout(pollTimer);closeModal();return render()}if(a==='add-site')return siteDialog();if(a==='save-site'){const f=$('#site-form'),data=formData('#site-form');b.disabled=true;if(f.dataset.id)await api('/sites/'+f.dataset.id,{method:'PATCH',data});else{const r=await api('/sites',{method:'POST',data});current=r.site}closeModal();view='Websites';await loadSites();return}if(a==='confirm-remove'){await api('/sites/'+d.id,{method:'DELETE'});if(current?.id===d.id)current=null;closeModal();view='Websites';return await loadSites()}if(a==='run'){b.disabled=true;await api('/sites/'+current.id+'/audits',{method:'POST'});view='Audits';await loadSite(current.id);toast('Audit queued. Progress and results will be saved.');return}if(a==='save-brand'){await changeSite({profile:formData('#brand-form')});toast('Brand and strategy saved. Run a new audit to use the updated context.');return}if(a==='save-draft'){await changeSite({draft:{id:d.id,text:$('#draft-text').value}});closeModal();toast('Notes saved. No website changes were made.');return}if(a==='add-keyword')return keywordDialog();if(a==='save-keyword'){const f=$('#keyword-form'),k={id:f.dataset.id,...formData('#keyword-form')};if(!k.phrase.trim()||!k.page.trim())throw Error('Add a phrase and page path.');await changeSite({keywords:[...current.keywords.filter(x=>x.id!==k.id),k]});closeModal();return}if(a==='save-access'){await changeSite({access:formData('#access-form')});toast('Access preferences saved.');return}if(a==='request-work'){if(!findings().length)throw Error('Run an audit and select findings first.');modal('Request implementation review','<p class="inline-note">This saves a request for review; it does not send an email, approve pricing or change your website.</p>'+findings().map(f=>'<label class="field"><span><input type="checkbox" data-request="'+f.id+'"> '+esc(f.title)+'</span></label>').join('')+field('note','Priorities, timing and questions','','textarea'),button('Save request','save-request','primary'));return}if(a==='save-request'){const ids=$$('[data-request]:checked').map(e=>e.dataset.request);await api('/sites/'+current.id+'/requests',{method:'POST',data:{findings:ids,note:$('#modal-root [name=note]').value}});closeModal();view='Website access';await loadSite(current.id,{keepAudit:true});return}if(a==='google-start'){b.disabled=true;const r=await api('/sites/'+current.id+'/google/start',{method:'POST'});location.assign(r.url);return}if(a==='google-disconnect'){modal('Disconnect Google?','<p>Remove the saved Google authorisation and cached analytics for this website. You can also revoke app access in your Google account.</p>',button('Disconnect','google-confirm-disconnect','dark'));return}if(a==='google-confirm-disconnect'){await api('/sites/'+current.id+'/google',{method:'DELETE'});closeModal();return await loadSite(current.id,{keepAudit:true})}if(a==='google-properties'){b.disabled=true;const p=await api('/sites/'+current.id+'/google/properties'),settings=connection.settings||{};modal('Choose your Google properties','<p class="inline-note">Select the properties you manage for this website. GA4 reports are filtered to this website hostname.</p>'+p.errors.map(e=>'<div class="error-note">'+esc(e)+'</div>').join('')+'<form id="google-properties"><label class="field">Search Console<select name="searchProperty"><option value="">Do not use Search Console</option>'+p.search.map(s=>'<option value="'+esc(s.siteUrl)+'" '+(s.siteUrl===settings.searchProperty?'selected':'')+'>'+esc(s.siteUrl)+'</option>').join('')+'</select></label><label class="field">Google Analytics 4<select name="analyticsProperty"><option value="">Do not use Analytics</option>'+p.analytics.map(p=>'<option value="'+esc(p.property)+'" '+(p.property===settings.analyticsProperty?'selected':'')+'>'+esc(p.displayName)+' · '+esc(p.property)+'</option>').join('')+'</select></label></form>',button('Save properties','google-save-properties','primary'));return}if(a==='google-save-properties'){await api('/sites/'+current.id+'/google/settings',{method:'POST',data:formData('#google-properties')});closeModal();return await loadSite(current.id,{keepAudit:true})}if(a==='google-sync'){b.disabled=true;toast('Refreshing the selected Google properties…');await api('/sites/'+current.id+'/google/sync',{method:'POST'});await loadSite(current.id,{keepAudit:true});toast('Refresh started. Results will update here when Google responds.');return}if(a==='print'){if(!result())throw Error('Run an audit first.');$('#print-only').innerHTML=reportHTML();$('#print-only').hidden=false;window.print();$('#print-only').hidden=true;return}if(a==='pdf')return pdfSummary();if(a==='audit-json'){if(!audit)throw Error('Run an audit first.');return download('synergy-hub-audit-evidence.json',JSON.stringify(audit,null,2),'application/json')}if(a==='csv'){const rows=[['priority','area','finding','url','evidence','recommendation','status'],...findings().map(f=>[f.priority,f.area,f.title,f.url,f.evidence,f.fix,current.tasks[f.id]||'To do'])];return download('synergy-hub-action-plan.csv',rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv')}if(a==='assistant'){const r=result();modal('Ask Synergy','<div class="actions"><img src="'+ASSETS.symbol+'" width="35" alt="Synergy Hub">'+pill('Evidence guide')+'</div><p class="inline-note">This guide summarises saved findings. It is not a general chat agent.</p>'+(r?'<div class="quote">'+esc(r.ai?.available?r.ai.summary:'Start with the highest-priority observed findings. Review page intent and evidence before making changes.')+'</div>'+findings().slice(0,3).map(f=>'<div class="list-row"><div><h3>'+esc(f.title)+'</h3><p class="inline-note">'+esc(f.fix)+'</p></div></div>').join(''):'<p class="inline-note">Run an audit to create evidence-led guidance.</p>'));return}}catch(err){toast(err.message)}finally{if(b.isConnected)b.disabled=false}});
document.addEventListener('change',async e=>{try{const el=e.target;if(el.id==='active-site'){view='Overview';await loadSite(el.value)}if(el.id==='audit-selection'&&el.value){const r=await api('/sites/'+current.id+'/audits/'+el.value);audit=r.audit;render()}if(el.dataset.task){await changeSite({task:{id:el.dataset.task,status:el.value}})}if(el.dataset.section){sections[el.dataset.section]=el.checked;render()}if(el.id==='finding-search'){query=el.value;render()}if(el.id==='logo-upload'){const f=el.files?.[0];if(!f)return;if(f.size>2e6||!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error('Use a PNG, JPG or WebP image under 2 MB.');const logo=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(f)});await changeSite({profile:{...formData('#brand-form'),logo}});toast('Logo saved to the workspace.')}if(el.id==='document-upload'){const f=el.files?.[0];if(!f)return;if(f.size>150000)throw Error('Use a text document under 150 KB.');const ext=f.name.split('.').pop().toLowerCase();if(!['txt','md'].includes(ext))throw Error('Upload TXT or Markdown with reviewed document text.');await api('/sites/'+current.id+'/documents',{method:'POST',data:{name:f.name,kind:ext==='md'?'text/markdown':'text/plain',content:await f.text()}});await loadSite(current.id,{keepAudit:true});toast('Document text saved. Review brand context before enabling AI analysis.')}}catch(err){toast(err.message)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
async function boot(){try{const s=await api('/session');user=s.user;csrf=s.csrf;if(user)await loadSites();else render();const status=new URL(location.href).searchParams.get('google');if(status)toast(status==='connected'?'Google authorisation stored. Select your website and choose properties in Connections.':'Google authorisation did not complete. Sign in and try again.');if(status)historyReplace()}catch(e){$('#app').innerHTML='<section class="card" style="margin:50px auto;max-width:650px"><h1>Unable to open your workspace.</h1><p class="spacer">'+esc(e.message)+'</p><p class="inline-note">Check the server and database configuration, then reload.</p></section>'}}
function historyReplace(){window.history.replaceState({},'',location.pathname)}
boot();
